      "content": "{\n  \"name\": \"@zzerx/dsh-plugin-usage-billing\",\n  \"version\": \"1.3.0\",\n  \"description\": \"计费显示：从既有会话日志聚合真实 token 用量，按事件时刻价格写时锁定费用；侧栏 / 输入框下方入口 + 点击弹层 + 设置页用量视图。\",\n  \"keywords\": [\n    \"dsh\",\n    \"deepseek-harness\",\n    \"plugin\",\n    \"usage-billing\",\n    \"token-usage\",\n    \"billing\",\n    \"cost\"\n  ],\n  \"homepage\": \"https://github.com/0x7A7A6572/dsh-forge-studio/tree/main/packages/plugin-usage-billing#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/0x7A7A6572/dsh-forge-studio/issues\"\n  },\n  \"license\": \"MIT\",\n  \"author\": \"0x7A7A\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/0x7A7A6572/dsh-forge-studio.git\",\n    \"directory\": \"packages/plugin-usage-billing\"\n  },\n  \"type\": \"module\",\n  \"main\": \"./lib/index.js\",\n  \"types\": \"./lib/types/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/types/client/index.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./shape\": {\n      \"types\": \"./lib/types/shape/index.d.ts\",\n      \"default\": \"./lib/shape.js\"\n    },\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib/index.js\",\n    \"lib/client.js\",\n    \"lib/shape.js\",\n    \"lib/types\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"LICENSE\"\n  ],\n  \"scripts\": {\n    \"prepublishOnly\": \"node scripts/build.mjs\",\n    \"build\": \"node scripts/build.mjs\",\n    \"push:npm\": \"npm publish --registry=https://registry.npmjs.org\",\n    \"typecheck\": \"tsc -p tsconfig.json --noEmit\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.4\",\n    \"@deepseek-ai/cordis-plugin-loader\": \"^1.0.5\",\n    \"@deepseek-ai/dsh-host-webserver\": \">=0.1.7-alpha.0 <0.3.0-0\",\n    \"@de