      "content": "{\n  \"name\": \"dsh-desk-studio\",\n  \"private\": true,\n  \"type\": \"module\",\n  \"scripts\": {\n    \"dev\": \"cross-env DSH_HOME=.dsh-home dsh web --port 3180\",\n    \"dsh\": \"cross-env DSH_HOME=.dsh-home dsh --port 3180\",\n    \"build\": \"pnpm -r --filter \\\"./packages/*\\\" run build\",\n    \"typecheck\": \"pnpm -r --filter \\\"./packages/*\\\" run typecheck\",\n    \"lint\": \"oxlint\",\n    \"lint:fix\": \"oxlint --fix\",\n    \"test\": \"vitest run\",\n    \"check\": \"pnpm lint && pnpm build && pnpm typecheck && pnpm test\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/dsh\": \"0.2.0-rc.1\",\n    \"cross-env\": \"7.0.3\",\n    \"lightningcss\": \"^1.33.0\",\n    \"oxlint\": \"^1.83.0\",\n    \"oxlint-tsgolint\": \"^7.0.2002\",\n    \"tsdown\": \"^0.22.14\",\n    \"vitest\": \"^5.0.1\"\n  }\n}\n"
