      "path": "packages/plugin-usage-billing/src/index.ts",
      "content": "import type { Context } from '@deepseek-ai/cordis'\nimport type { SessionEvent, SessionHeader } from '@deepseek-ai/dsh-session'\nimport { usageBillingDomain } from './domain.ts'\nimport { UsageBillingService } from './service.ts'\nimport { installUsageBillingSettings, configureUsageBillingSettingsPage, type Config } from './settings.ts'\nimport type { SessionSource } from './aggregate.ts'\nimport { BUILTIN_CATALOG, DEFAULT_USD_TO_CNY } from './pricing/catalog.ts'\nimport { fetchPricingFromNetwork } from './pricing/fetch.ts'\nimport { createThemeTranspiler } from './themes/transpile.ts'\nimport { installThemesRoute } from './themes/route.ts'\nimport { resolveThemesRoot } from './themes/discover.ts'\n\nexport const name = '@zzerx/dsh-plugin-usage-billing'\nexport const inject = ['storageDomain']\n/** 设置分区的命名空间就是本条目 id。 */\nexport { Config } from './settings.ts'\n\nconst REFRESH_CHECK_MS = 60_000\n\ninterface SessionQueryLike {\n  listSessions(): Promise<Array<{ header: SessionHeader }>>\n  readSession(id: string): Promise<{ session: SessionHeader; events: SessionEvent[] }>\n}\n\n/** revision 由文件 stat 身份生成，不读会话正文。 */\ninterface SessionPersistenceLike {\n  list(options?: { signal?: AbortSignal }): Promise<readonly { header: SessionHeader; revision: string }[]>\n}\n\nexport async function apply(ctx: Context, config: Config): Promise<void> {\n  const domainService = ctx.get('storageDomain')\n  if (domainService === undefined) {\n    ctx.logger.warn('[plugin-usage-billing] storageDomain 未装配，计费聚合不可用（插件已降级）')\n    return\n  }\n\n  const domain = await domainService.open(usageBillingDomain)\n  ctx.effect(() => () => { void domain.close() })\n\n  const settings = installUsageBillingSettings(ctx, config)\n  // webServer 不进顶层 inject：那样激活就依赖 WebServer；交给 ctx.inject 后服务后到也会补挂。\n  // 转译器只建一个：缓存挂在实例上。\n  const disposeThemes = installThemesRoute(ctx, {\n    root: resolveThemesRoot(),\n    transpiler: createThemeTranspiler(),\n  })\n  ctx.effect(() => () => { disposeThemes() })\n  configureUsageBillingSettingsPage(ctx)\n  /** 本次加载时刻，非首次安装时刻：之后由 `reason: 'install'` 的快照留存。 */\n  const installAt = Date.now()\n\n  // 判据是「账本里没有 install 层」，不是「表是空的」。\n  const snapshots = domain.table('snapshots')\n\n  const source: SessionSource = {\n    listSessions: async () => {\n      const persistence = ctx.get('sessionPersistence') as SessionPersistenceLike | undefined\n      if (persistence !== undefined) {\n        const listed = await persistence.list()\n        return listed.map((s) => ({ header: s.header, stamp: String(s.revision) }))\n      }\n      // 退化：stamp 为 null，该轮每个会话整会话重读。\n      const q = ctx.get('sessionQuery') as SessionQueryLike | undefined\n      if (q === undefined) return []\n      return (await q.listSessions()).map((r) => ({ header: r.header, stamp: null }))\n    },\n    readSession: async (id: string) => {\n      const q = ctx.get('sessionQuery') as SessionQueryLike | undefined\n      if (q === undefined) throw new Error('sessionQuery unavailable')\n      const snap = await q.readSession(id as never)\n      return { session: snap.session, events: [...snap.events] }\n    },\n  }\n\n  const service = new UsageBillingService(ctx, {\n    domain,\n    settings,\n    installAt,\n    source,\n    fetchPricing: async ({ force, ttlHours }) => {\n      const web = ctx.get('web')\n      if (web === undefined) return { ok: false, reason: 'web 服务未装配' }\n      return await fetchPricingFromNetwork({ web, snapshots, now: () => Date.now() }, force, ttlHours)\n    },\n  })\n\n  // 同时充当「安装前历史」的回填口径。\n  await service.ensureBaseSnapshot({ ...BUILTIN_CATALOG }, DEFAULT_USD_TO_CNY, 'default')\n\n  // 预热与定时刷新的 timer / disposer 都归属当前 fiber。\n  ctx.effect(() => {\n    // 预热与读端点共用同一条合并通道，不另起一趟全量扫描。\n    // repricing 只碰 unpriced 行，已锁定的行不改写。\n    // 首启或上次重建未收尾时先整语料重折：旧水位指向旧容器。\n    const preheat = domain.global.get().rebuiltAt === undefined\n      ? service.rebuildLedger().then((stats) => {\n        if (stats.failures > 0) {\n          // 不落标记：失败会话水位未推进，下次启动整趟重来。\n          ctx.logger.warn(`[plugin-usage-billing] 账本分片重建有 ${stats.failures} 个会话失败，下次启动重来`)\n        } else {\n          ctx.logger.info(`[plugin-usage-billing] 账本分片重建完成：${stats.rows} 行 / ${domain.table('ledger_shards').size} 个分片`)\n        }\n      })\n      : service.warmup()\n\n    void preheat\n      .then(() => service.repricing())\n      .then((result) => {\n        if (result.changed > 0) {\n          ctx.logger.info(`[plugin-usage-billing] 启动重算：${result.changed} 行未计价记录已按现价表补价`)\n        }\n      })\n      .catch((error: unknown) => {\n        ctx.logger.warn('[plugin-usage-billing] 预热聚合失败：', error)\n      })\n\n    const timer = setInterval(() => {\n      try {\n        const cfg = settings.get()\n        if (!cfg.pricing.autoRefresh) return\n        // 失败有两种：Promise 拒绝、{ ok: false } 返回，两条都要落日志。\n        void service.refreshPricing(false)\n          .then((result) => {\n            if (!result.ok) ctx.logger.warn('[plugin-usage-billing] 后台刷新失败：', result.reason)\n          })\n          .catch((error: unknown) => {\n            ctx.logger.warn('[plugin-usage-billing] 后台刷新异常：', error)\n          })\n      } catch (error) {\n        ctx.logger.warn('[plugin-usage-billing] 刷新调度失败：', error)\n      }\n    }, REFRESH_CHECK_MS)\n    return () => clearInterval(timer)\n  })\n}\n"
    },
    {
      "path": "packages/plugin-usage-billing/src/fold.ts",
      "content": "/**\n * 折叠：把一条会话的事件序列折成账本行（纯函数，不碰 storage、不做 IO）。\n *\n * 归属规则（spec §5.1）：request/context 的 {provider, model} 优先于\n * request/header 的 data.header.config；两者皆缺记 'unknown'，不丢账。\n * 计价规则（spec §5.3/§5.4）：**每条事件用它自己的 time 解析价表**，金额随即锁定。\n * 行 id = `ledgerKey(sessionId, seq)`（`<sessionId>__<seq>`，见 `storage-key.ts`），\n * 因此重复折叠是幂等 upsert。\n */\n\nimport type { SessionEvent, SessionHeader } from '@deepseek-ai/dsh-session'\nimport { aliasId, priceKeyCandidates } from './model-key.ts'\nimport { priceUsage } from './pricing/cost.ts'\nimport { isCnHoliday } from './pricing/holidays.ts'\nimport { tierAndFactorAt } from './pricing/tiers.ts'\nimport type { ResolvedTable } from './pricing/snapshot.ts'\nimport { ledgerKey } from './storage-key.ts'\nimport { dayKey } from './time.ts'\nimport type { LedgerRow, ModelAlias } from './types.ts'\n\nexport interface FoldContext {\n  session: SessionHeader\n  /** 首次装配时刻：早于它的事件标 backfilled。 */\n  installAt: number\n  aliases: ReadonlyMap<string, ModelAlias>\n  resolvePrice: (at: number) => ResolvedTable\n}\n\nexport interface FoldResult {\n  rows: LedgerRow[]\n  lastSeq: number\n  lastTime: number\n  /** 模型调用次数（含无 usage 与未计价的调用）。 */\n  calls: number\n  /** 未命中的 `${provider}/${model}`，供 UI 提示计数。 */\n  unpricedModels: Set<string>\n}\n\ninterface Attribution { provider: string; model: string }\n\nconst UNKNOWN: Attribution = { provider: 'unknown', model: 'unknown' }\n\nexport function foldEvents(events: readonly SessionEvent[], ctx: FoldContext): FoldResult {\n  const rows: LedgerRow[] = []\n  const unpricedModels = new Set<string>()\n  let fromContext: Attribution | undefined\n  let fromHeader: Attribution | undefined\n  // 种子 -1：seq 0 的会话才有可用的空序列哨兵（0 会让它永远被水位跳过）。\n  let lastSeq = -1\n  let lastTime = 0\n  let calls = 0\n\n  for (const event of events) {\n    if (event.seq > lastSeq) lastSeq = event.seq\n    if (event.time > lastTime) lastTime = event.time\n\n    if (event.type === 'request/context') {\n      const d = event.data as { provider?: unknown; model?: unknown }\n      if (typeof d.provider === 'string' && typeof d.model === 'string') {\n        fromContext = { provider: d.provider, model: d.model }\n      }\n      continue\n    }\n    if (event.type === 'request/header') {\n      const cfg = (event.data as { header?: { config?: { provider?: unknown; model?: unknown } } }).header?.config\n      if (typeof cfg?.provider === 'string' && typeof cfg.model === 'string') {\n        fromHeader = { provider: cfg.provider, model: cfg.model }\n      }\n      continue\n    }\n    if (event.type !== 'assistant/message') continue\n\n    calls += 1\n    const usage = (event.data as { usage?: import('@deepseek-ai/dsh-llm').TokenUsage }).usage\n    if (usage === undefined) continue\n\n    const who = fromContext ?? fromHeader ?? UNKNOWN\n    const alias = ctx.aliases.get(aliasId(who.provider, who.model))\n    const table = ctx.resolvePrice(event.time)\n    const keys = priceKeyCandidates(who.provider, who.model, alias)\n    const { tier, factor } = tierAndFactorAt(event.time, isCnHoliday)\n    const priced = priceUsage(usage, table.entries, keys, table.usdToCny, factor)\n    const modelLabel = `${who.provider}/${who.model}`\n    if (!priced.priced) unpricedModels.add(modelLabel)\n\n    rows.push({\n      id: ledgerKey(ctx.session.id, event.seq),\n      sessionId: ctx.session.id,\n      seq: event.seq,\n      time: event.time,\n      provider: who.provider,\n      model: who.model,\n      day: dayKey(event.time),\n      ...(ctx.session.cwd === undefined ? {} : { cwd: ctx.session.cwd }),\n      isSubagent: ctx.session.origin === 'subagent',\n      ...(ctx.session.delegationDepth === undefined ? {} : { delegationDepth: ctx.session.delegationDepth }),\n      input: usage.inputTokens,\n      cacheRead: usage.cacheReadTokens ?? 0,\n      cacheWrite: usage.cacheWriteTokens ?? 0,\n      output: usage.outputTokens,\n      reasoning: usage.reasoningTokens ?? 0,\n      costCny: priced.costCny,\n      currency: priced.currency,\n      priced: priced.priced,\n      snapshotId: table.snapshotId,\n      ...(tier === null ? {} : { tier }),\n      backfilled: event.time < ctx.installAt,\n    })\n  }\n\n  return { rows, lastSeq, lastTime, calls, unpricedModels }\n}\n"
    },
    {
      "path": "packages/plugin-usage-billing/src/aggregate.ts",
      "content": "/**\n * 聚合驱动：列会话 → 用**变更戳**判断是否要重折 → readSession 取正文 → foldEvents →\n * 幂等 upsert 账本 → 写水位。\n *\n * 为什么不用 `sessionQuery.listEvents` 探水位（实测故障）：它名字像\"只取元数据\"，\n * 实现却是 `SessionCorpus.load` —— 每调一次都把整个语料再列一遍、再把那个会话完整\n * 解码并克隆全部事件，全程无缓存。107 个会话 = 一趟 107 次全量列举 + 107 次整会话解码，\n * 分钟级；而每个读接口都在等这一趟。变更戳由持久化后端在**一次 `list()`** 里给全\n * （stat 身份，不读正文），所以改用它。\n *\n * 容错（spec §8）：单会话 readSession 抛错只跳过它、记诊断、**不推进水位**（下次重试），\n * 其余会话照常。诊断按 (sessionId, kind) 稳定键 upsert 并受上限约束，重试风暴不会涨存储。\n * 全量结果有 TTL 缓存以合并密集轮询；同进程的并发调用由 service 侧合并成一趟。\n */\n\nimport type { SessionEvent, SessionHeader } from '@deepseek-ai/dsh-session'\nimport type { KvTable } from '@deepseek-ai/dsh-storage-domain'\nimport type { LedgerWriter } from './ledger-store.ts'\nimport { recordDiagnostic, trimDiagnostics } from './diag.ts'\nimport { foldEvents } from './fold.ts'\nimport { resolveSnapshotAt } from './pricing/snapshot.ts'\nimport { sameRow } from './shard-merge.ts'\nimport { foldKey } from './storage-key.ts'\nimport type { Diagnostic, FoldState, ModelAlias, PriceSnapshot } from './types.ts'\n\nexport interface SessionSource {\n  /**\n   * 一次轻量列举：每个会话只给 header 与变更戳。**不得**为了拿戳而读会话正文。\n   * `stamp === null` = 后端给不出变更戳，那一轮只能整会话重读（退化路径，慢但正确）。\n   */\n  listSessions(): Promise<Array<{ header: SessionHeader; stamp: string | null }>>\n  /**\n   * 读取一个会话的**完整**事件序列。\n   *\n   * 必须包含 ≤ `maxSeq` 的全部 seq，不得截断、也不得挖空中间段：返回不完整会让\n   * 未读事件漏折。分页/继承裁剪的实现必须把它们拼成完整序列再返回。\n   */\n  readSession(id: string): Promise<{ session: SessionHeader; events: SessionEvent[] }>\n}\n\nexport interface AggregateDeps {\n  source: SessionSource\n  /** 只读一行 / 写一行：分片容器由 LedgerStore 兜住，聚合对容器粒度无感。 */\n  ledger: LedgerWriter\n  folds: KvTable<string, FoldState>\n  diag: KvTable<string, Diagnostic>\n  aliases: KvTable<string, ModelAlias>\n  snapshots: KvTable<string, PriceSnapshot>\n  installAt: number\n  now?: () => number\n  ttlMs?: number\n}\n\nexport interface AggregateStats {\n  sessions: number\n  folded: number\n  skipped: number\n  rows: number\n  failures: number\n  unpricedModels: string[]\n  cached: boolean\n}\n\n/**\n * TTL 缓存（模块级：同一 host 内共享）。\n *\n * 选项语义（**别改成三态**）：`force` 为真只绕过这个 TTL 缓存，**变更戳始终生效** ——\n * 手动刷新仍然便宜，因为没变过的会话连 `readSession` 都不会调。\n * 不重复计费由账本行 id `ledgerKey(sessionId, seq)`（`<sessionId>__<seq>`）的幂等 upsert\n * 保证，不靠水位。\n */\nlet lastRun: { at: number; stats: AggregateStats } | undefined\n\nexport function resetAggregateCache(): void { lastRun = undefined }\n\nexport async function aggregateOnce(\n  deps: AggregateDeps,\n  opts: { force?: boolean; rebuild?: boolean } = {},\n): Promise<AggregateStats> {\n  const now = deps.now ?? (() => Date.now())\n  const ttl = deps.ttlMs ?? 5_000\n  if (!opts.force && lastRun !== undefined && now() - lastRun.at < ttl) {\n    return { ...lastRun.stats, cached: true }\n  }\n\n  const snapshots = [...deps.snapshots.entries()].map(([, s]) => s)\n  const aliasMap = new Map<string, ModelAlias>()\n  for (const [, a] of deps.aliases.entries()) aliasMap.set(a.id, a)\n\n  const sessions = await deps.source.listSessions()\n  let folded = 0; let skipped = 0; let rows = 0; let failures = 0\n  const unpriced = new Set<string>()\n\n  for (const { header, stamp } of sessions) {\n    try {\n      const wm = deps.folds.get(foldKey(header.id))\n      // 戳相同 = 这份日志自上次折叠以来没变过；headerCreatedAt 只是 id 复用时的兜底。\n      // `rebuild` 那一趟**故意不看水位**：账本换容器后水位对应的是旧容器，必须整语料重折一遍。\n      if (!opts.rebuild && wm !== undefined && stamp !== null && wm.stamp === stamp && wm.headerCreatedAt === header.createdAt) {\n        skipped += 1\n        continue\n      }\n      const snap = await deps.source.readSession(header.id)\n      const result = foldEvents(snap.events, {\n        session: snap.session,\n        installAt: deps.installAt,\n        aliases: aliasMap,\n        resolvePrice: (at) => resolveSnapshotAt(at, snapshots),\n      })\n      // 一个会话一轮只写一次：它的行落在同一片（跨天最多两片）上，逐行写会把整片重写几十遍。\n      // 只有内容真的变了才落盘：正在写的会话每轮都会被重折，绝大多数行是上一轮的旧行。\n      const changed = result.rows.filter((row) => {\n        const previous = deps.ledger.get(row.id)\n        return previous === undefined || !sameRow(previous, row)\n      })\n      await deps.ledger.putMany(changed)\n      await deps.folds.put(foldKey(header.id), {\n        sessionId: header.id,\n        // 戳为 null 时不写这个字段：下一轮继续整会话重读，等后端能给出戳为止。\n        ...(stamp === null ? {} : { stamp }),\n        foldedThroughSeq: result.lastSeq,\n        lastTime: result.lastTime,\n        headerCreatedAt: header.createdAt,\n        lastSnapshotId: resolveSnapshotAt(result.lastTime, snapshots).snapshotId,\n      })\n      for (const m of result.unpricedModels) unpriced.add(m)\n      folded += 1\n      rows += result.rows.length\n    } catch (error) {\n      failures += 1\n      // 诊断写入本身还可能失败（storage 抖了），而它是唯一的副作用：让它自己兜住，\n      // 否则一个坏会话会把其余会话一起带走。header 也可能缺失，先本地取值再拼内容。\n      // 键稳定于 (sessionId, kind)：同一个坏会话重试多少次都只 upsert 同一条，\n      // 不推进水位意味着它下轮还会被重试 —— 但重试只累加计数，不会再涨存储。\n      const sessionId = header?.id ?? '<unknown>'\n      try {\n        await recordDiagnostic(deps.diag, {\n          sessionId, kind: 'session-read', at: now(),\n          detail: `${sessionId}: ${error instanceof Error ? error.message : String(error)}`,\n        })\n      } catch { /* 诊断写不进去也不能中断后续会话 */ }\n    }\n  }\n\n  // 上限收口放在整轮末尾（而不是每条失败一次）：一轮最多多出「本轮坏会话数」条，\n  // 结束后立刻回到上限之内 —— 重试风暴无法让 diag 表无界增长。清理失败不拖垮聚合。\n  try {\n    await trimDiagnostics(deps.diag)\n  } catch { /* 诊断清理失败只是留下多余记录，不该让本轮聚合失败 */ }\n\n  const stats: AggregateStats = {\n    sessions: sessions.length, folded, skipped, rows, failures,\n    unpricedModels: [...unpriced].sort(), cached: false,\n  }\n  lastRun = { at: now(), stats }\n  return stats\n}\n\n"
    },
    {
      "path": "packages/plugin-usage-billing/src/ledger-store.ts",
      "content": "/**\n * LedgerStore —— 账本行的唯一读写通道，站在分片容器之上。\n *\n * 为什么必须有串行链：分片是「读整片 → 改 → 写整片」，而 domain 的 `put` 是「先落盘、\n * 再改内存、再发事件」，**读却始终是同步的**。两个并发写会各自读到同一份旧分片，\n * 后写把先写整片覆盖掉（丢行）。所以所有触碰分片的操作都排在同一条链上，\n * 链内每一步读到的都是上一步落盘后的状态。\n *\n * 为什么要有内存索引：聚合每轮都要按行 id 判重（`get(row.id)`），逐次扫分片表会把 O(1)\n * 变成 O(分片数)；索引在构造时一次性建立、之后随写入维护。行本身不复制，只存引用。\n *\n * 为什么写入要成批（`putMany`）：一片是一个记录，写一行就要整片重写。首次重建有 2 万行、\n * 每片几十行，逐行写等于把同一片反复重写几十遍（实测字节放大 22.8 倍）；按会话成批后\n * 一片一轮只写一次。\n */\n\nimport type { KvTable } from '@deepseek-ai/dsh-storage-domain'\nimport { emptyShard, mergeShardRows, sameRow } from './shard-merge.ts'\nimport { ledgerShardKey } from './storage-key.ts'\nimport type { LedgerRow, LedgerShard } from './types.ts'\n\n/**\n * 聚合侧对账本的**最小**需求。方法与原 `KvTable` 的同名成员同形，调用点不必改写法。\n */\nexport interface LedgerWriter {\n  get(id: string): LedgerRow | undefined\n  /** 成批写：同一分片的行合并成一次落盘，没变的行不写。 */\n  putMany(rows: readonly LedgerRow[]): Promise<void>\n}\n\n/** 一批写入在某个分片上的增删，用来把「同一片的多行」缩成一次读写。 */\ninterface ShardPatch {\n  sessionId: string\n  day: string\n  /** 要从这片摘掉的行 id（同一行换了天）。 */\n  outgoing: Set<string>\n  /** 要并入这片的行。 */\n  incoming: Map<string, LedgerRow>\n}\n\nexport class LedgerStore implements LedgerWriter {\n  private readonly table: KvTable<string, LedgerShard>\n  private readonly rowsById = new Map<string, LedgerRow>()\n  /** 写链的尾；每个链接都自行吞掉 rejection，前一次失败不卡死后面的写入。 */\n  private chain: Promise<unknown> = Promise.resolve()\n\n  constructor(table: KvTable<string, LedgerShard>) {\n    this.table = table\n    for (const [, shard] of table.entries()) {\n      for (const row of shard.rows) this.rowsById.set(row.id, row)\n    }\n  }\n\n  get size(): number { return this.rowsById.size }\n\n  /** 分片记录数（诊断/验收用：这就是冷启动要打开的文件数）。 */\n  get shardCount(): number { return this.table.size }\n\n  get(id: string): LedgerRow | undefined { return this.rowsById.get(id) }\n\n  /** 全量快照（视图层按窗口过滤，不在这里裁剪）。 */\n  all(): LedgerRow[] { return [...this.rowsById.values()] }\n\n  put(id: string, row: LedgerRow): Promise<void> { return this.putMany([row]) }\n\n  putMany(rows: readonly LedgerRow[]): Promise<void> {\n    if (rows.length === 0) return Promise.resolve()\n    const run = this.chain.then(() => this.applyRows(rows))\n    this.chain = run.then(() => undefined, () => undefined)\n    return run\n  }\n\n  /** 链内执行：把一批行落到它们各自的分片上，每片至多一次读写。 */\n  private async applyRows(batch: readonly LedgerRow[]): Promise<void> {\n    const patches = new Map<string, ShardPatch>()\n    const patchAt = (key: string, sessionId: string, day: string): ShardPatch => {\n      let patch = patches.get(key)\n      if (patch === undefined) {\n        patch = { sessionId, day, outgoing: new Set(), incoming: new Map() }\n        patches.set(key, patch)\n      }\n      return patch\n    }\n\n    for (const row of batch) {\n      const previous = this.rowsById.get(row.id)\n      if (previous !== undefined) {\n        const oldKey = ledgerShardKey(previous.sessionId, previous.day)\n        const newKey = ledgerShardKey(row.sessionId, row.day)\n        if (oldKey === newKey) {\n          // 同片且内容未变：整片不写。正在写的会话每轮都会被重折，绝大多数行是旧行。\n          if (sameRow(previous, row)) continue\n        } else {\n          // 换了分片（会话日志被改写导致 day 变了）：先从旧片摘掉，否则同一个 seq\n          // 会在两片里各留一份，等于重复计费。\n          patchAt(oldKey, previous.sessionId, previous.day).outgoing.add(row.id)\n        }\n      }\n      const target = patchAt(ledgerShardKey(row.sessionId, row.day), row.sessionId, row.day)\n      target.incoming.set(row.id, row)\n    }\n\n    for (const [key, patch] of patches) {\n      const current = this.table.get(key)\n      const kept = current === undefined\n        ? []\n        : current.rows.filter((candidate) => !patch.outgoing.has(candidate.id))\n      const merged = mergeShardRows(kept, [...patch.incoming.values()])\n      if (merged.rows.length === 0) {\n        // 摘空即删键：不留空壳，否则每次冷启动都白读一个文件。\n        if (current !== undefined) await this.table.delete(key)\n      } else if (merged.changed || patch.outgoing.size > 0) {\n        await this.table.put(key, emptyShard(patch.sessionId, patch.day, merged.rows))\n      }\n      for (const id of patch.outgoing) this.rowsById.delete(id)\n      for (const row of patch.incoming.values()) this.rowsById.set(row.id, row)\n    }\n  }\n}\n"
    },
    {
      "path": "packages/plugin-usage-billing/src/pricing/cost.ts",
      "content": "/**\n * 计价：TokenUsage 的四个互斥桶 × 单价四项。\n * 口径见 spec §5.2 —— inputTokens 不含缓存部分，所以 input / cacheRead / cacheWrite\n * 三者相加才是计费输入；reasoningTokens 已并入 output 计数，不单独计价。\n * 未命中任何价目时 priced=false 且 cost=0，由 UI 显著标注，绝不猜价。\n */\n\nimport type { TokenUsage } from '@deepseek-ai/dsh-llm'\nimport { WILDCARD, normalizeModelId } from '../model-key.ts'\nimport type { Currency, PriceEntry } from '../types.ts'\n\nexport interface SplitUsage {\n  input: number\n  cacheRead: number\n  cacheWrite: number\n  output: number\n  reason: number | undefined\n}\n\nexport interface PriceResult {\n  costCny: number\n  currency: Currency\n  priced: boolean\n  matchedKey: string | null\n  /** 命中 keys 中的第几档（0 起）；未命中为 -1。 */\n  matchRank: number\n}\n\n/** 拆四桶（缺失的缓存字段按 0）。 */\nexport function splitUsage(usage: TokenUsage): SplitUsage {\n  return {\n    input: usage.inputTokens,\n    cacheRead: usage.cacheReadTokens ?? 0,\n    cacheWrite: usage.cacheWriteTokens ?? 0,\n    output: usage.outputTokens,\n    reason: usage.reasoningTokens,\n  }\n}\n\n/** 同名兜底候选的前缀：首段 `*` + 斜杠 + 模型名 = 「任何 provider 下叫这个名字的价」。 */\nconst NAME_FALLBACK_PREFIX = `${WILDCARD}/`\n\n/**\n * 表内「模型名 → 命中键」索引（延迟构建，按表的键**插入顺序**取第一条）。\n *\n * 插入顺序即优先级来源：内置目录在安装时就写进基准快照，网络刷新只会往后追加 delta，\n * 所以同一个模型名有多个 provider 时先出现的（目录里的官方 provider）胜出 —— 确定性、可解释。\n *\n * 用 WeakMap 挂在价目表本身上：快照表是不可变对象，按表缓存不会串味，也不会泄漏。\n */\nconst nameIndexCache = new WeakMap<object, Map<string, string>>()\n\n/** 表内同名条目键；没有则 undefined。 */\nfunction sameNameEntryKey(table: Readonly<Record<string, PriceEntry>>, name: string): string | undefined {\n  let index = nameIndexCache.get(table)\n  if (index === undefined) {\n    index = new Map<string, string>()\n    for (const key of Object.keys(table)) {\n      const slash = key.indexOf('/')\n      if (slash <= 0) continue\n      const modelPart = key.slice(slash + 1)\n      // `<provider>/*` 与 `*/*` 是兜底价，不是「某个模型的同名价」。\n      if (modelPart === WILDCARD) continue\n      const normalized = normalizeModelId(modelPart)\n      if (normalized !== '' && !index.has(normalized)) index.set(normalized, key)\n    }\n    nameIndexCache.set(table, index)\n  }\n  return index.get(normalizeModelId(name))\n}\n\n/**\n * 解析一个候选键：先按字面命中；首段为 `*` 的候选再走同名兜底。\n * @param table - 该时刻解析出的价目表（`<provider>/<model>` → 单价）。\n * @param key - 候选键，见 `priceKeyCandidates`。\n */\nfunction entryFor(table: Readonly<Record<string, PriceEntry>>, key: string): PriceEntry | undefined {\n  const direct = table[key]\n  if (direct !== undefined) return direct\n  if (!key.startsWith(NAME_FALLBACK_PREFIX)) return undefined\n  const hit = sameNameEntryKey(table, key.slice(NAME_FALLBACK_PREFIX.length))\n  return hit === undefined ? undefined : table[hit]\n}\n\n/**\n * 按 keys 顺序查价并计价（首段为 `*` 的候选 = 同名兜底，见 `priceKeyCandidates`）。\n * @param priceFactor - 档位系数：空闲档传规则倍率（官方 0.5），高峰档省略。\n */\nexport function priceUsage(\n  usage: TokenUsage,\n  table: Readonly<Record<string, PriceEntry>>,\n  keys: readonly string[],\n  usdToCny: number,\n  priceFactor = 1,\n): PriceResult {\n  for (let rank = 0; rank < keys.length; rank++) {\n    const key = keys[rank]!\n    const entry = entryFor(table, key)\n    if (entry === undefined) continue\n    if (entry.currency === 'USD' && !(usdToCny > 0)) {\n      // 汇率不可用：宁可标成「不可计价」也不锁一个 0 进账本。\n      // matchedKey 非 null 是它与「未收录」（matchedKey === null）的区别。\n      return { costCny: 0, currency: entry.currency, priced: false, matchedKey: key, matchRank: rank }\n    }\n    const s = splitUsage(usage)\n    const native = (s.input * entry.input + s.cacheRead * entry.cacheRead\n      + s.cacheWrite * entry.cacheWrite + s.output * entry.output) / 1_000_000 * priceFactor\n    const costCny = entry.currency === 'USD' ? native * usdToCny : native\n    return {\n      costCny: Math.max(0, costCny),\n      currency: entry.currency,\n      priced: true,\n      matchedKey: key,\n      matchRank: rank,\n    }\n  }\n  return { costCny: 0, currency: 'CNY', priced: false, matchedKey: null, matchRank: -1 }\n}\n"
    },
    {
      "path": "packages/plugin-usage-billing/src/pricing/tiers.ts",
      "content": "/** 峰谷时段规则与判档；节假日由调用方注入（tyme4ts 只准出现在宿主侧）。 */\n\nexport type Tier = 'peak' | 'offPeak'\n\nexport interface TierRule {\n  /** 生效起点（epoch ms，含）。 */\n  since: number\n  /** 高峰窗口，北京时间分钟，左闭右开。 */\n  peakWindows: readonly (readonly [number, number])[]\n  weekdaysOnly: boolean\n  /** 'CN' = 中国法定节假日全天算空闲。 */\n  holidays: 'CN'\n  offPeakRatio: number\n}\n\n/** 今日费率形状；与判档共用同一份窗口，客户端只做几何。 */\nexport interface TierDayProfile {\n  /** 工作日且非节假日；false 时 peakWindows 为空。 */\n  workday: boolean\n  peakWindows: readonly (readonly [number, number])[]\n  offPeakRatio: number\n  utcOffsetMinutes: number\n}\n\nconst PEAK_WINDOWS = [[540, 720], [840, 1080]] as const\n\n/** 起点取参考实现记录的政策变更点（北京 2026-08-17，官网未标日期）。 */\nexport const TIER_RULES: readonly TierRule[] = [\n  {\n    since: Date.UTC(2026, 7, 16, 16),\n    peakWindows: PEAK_WINDOWS,\n    weekdaysOnly: true,\n    holidays: 'CN',\n    offPeakRatio: 0.5,\n  },\n]\n\nconst DAY_MS = 86_400_000\nconst CN_OFFSET_MS = 8 * 3_600_000\n\n/** 规则时区相对 UTC 的分钟偏移（北京 480）；曲线横轴用该时区的自然日。 */\nexport const RULE_UTC_OFFSET_MINUTES = CN_OFFSET_MS / 60_000\n\nfunction beijingMinuteOfDay(timeMs: number): number {\n  return Math.floor((((timeMs + CN_OFFSET_MS) % DAY_MS) + DAY_MS) % DAY_MS / 60_000)\n}\n\nfunction beijingWeekday(timeMs: number): number {\n  return new Date(timeMs + CN_OFFSET_MS).getUTCDay()\n}\n\n/** 生效规则；null = 该时刻属于单档年代。 */\nexport function tierRuleAt(timeMs: number): TierRule | null {\n  let hit: TierRule | null = null\n  for (const rule of TIER_RULES) if (timeMs >= rule.since) hit = rule\n  return hit\n}\n\n/**\n * 下一个档位切换时刻。候选只有北京时间 00:00 与窗口端点。\n * @returns 规则未生效或 8 天内不变则 null。\n */\nexport function nextTierSwitchAt(now: number, isHoliday: (timeMs: number) => boolean): number | null {\n  const rule = tierRuleAt(now)\n  if (rule === null) return null\n  const current = tierAt(now, isHoliday)\n  const dayStart = Math.floor((now + CN_OFFSET_MS) / DAY_MS) * DAY_MS - CN_OFFSET_MS\n  for (let i = 0; i < 8; i++) {\n    const base = dayStart + i * DAY_MS\n    const edges = rule.peakWindows.flatMap(([from, to]) => [base + from * 60_000, base + to * 60_000])\n    for (const at of [base, ...edges].sort((a, b) => a - b)) {\n      if (at <= now) continue\n      if (tierAt(at, isHoliday) !== current) return at\n    }\n  }\n  return null\n}\n\nexport function tierAndFactorAt(\n  timeMs: number,\n  isHoliday: (timeMs: number) => boolean,\n): { tier: Tier | null; factor: number } {\n  const rule = tierRuleAt(timeMs)\n  if (rule === null) return { tier: null, factor: 1 }\n  const tier = tierAt(timeMs, isHoliday)\n  return { tier, factor: tier === 'offPeak' ? rule.offPeakRatio : 1 }\n}\n\nfunction offDay(rule: TierRule, timeMs: number, isHoliday: (timeMs: number) => boolean): boolean {\n  if (rule.weekdaysOnly) {\n    const dow = beijingWeekday(timeMs)\n    if (dow === 0 || dow === 6) return true\n  }\n  return rule.holidays === 'CN' && isHoliday(timeMs)\n}\n\n/** 无生效规则 / 查不出节假日时按高峰计。 */\nexport function tierAt(timeMs: number, isHoliday: (timeMs: number) => boolean): Tier {\n  const rule = tierRuleAt(timeMs)\n  if (rule === null) return 'peak'\n  if (offDay(rule, timeMs, isHoliday)) return 'offPeak'\n  const minute = beijingMinuteOfDay(timeMs)\n  for (const [from, to] of rule.peakWindows) if (minute >= from && minute < to) return 'peak'\n  return 'offPeak'\n}\n\nexport function tierDayProfileAt(\n  now: number,\n  isHoliday: (timeMs: number) => boolean,\n): TierDayProfile | null {\n  const rule = tierRuleAt(now)\n  if (rule === null) return null\n  const workday = !offDay(rule, now, isHoliday)\n  return {\n    workday,\n    peakWindows: workday ? rule.peakWindows : [],\n    offPeakRatio: rule.offPeakRatio,\n    utcOffsetMinutes: RULE_UTC_OFFSET_MINUTES,\n  }\n}\n"
    },
    {
      "path": "packages/plugin-usage-billing/src/shard-merge.ts",
      "content": "/**\n * 分片合并 —— 幂等内核（纯函数，不碰 storage、不做 IO）。\n *\n * 为什么单独成文件：行身份从「存储键唯一」搬到「分片内 id 唯一」之后，幂等就从存储层\n * 保证变成这里的不变量；它必须能脱离 storage 单测（历史上正是「假表从不校验键」\n * 让一次全量写失败瞒过了全部用例）。\n */\n\nimport type { LedgerRow, LedgerShard } from './types.ts'\n\n/** 分片记录的当前格式版本。 */\nexport const SHARD_VERSION = 1\n\nexport interface ShardMerge {\n  rows: LedgerRow[]\n  /** 批次有没有真的改动；false 时调用方必须跳过整片重写。 */\n  changed: boolean\n}\n\nexport function emptyShard(sessionId: string, day: string, rows: LedgerRow[] = []): LedgerShard {\n  return { v: SHARD_VERSION, sessionId, day, rows }\n}\n\n/** 逐字段比较两行账本（值都是原始类型，`!==` 即可；键集合不同即视为变了）。 */\nexport function sameRow(a: LedgerRow, b: LedgerRow): boolean {\n  const left = a as unknown as Record<string, unknown>\n  const right = b as unknown as Record<string, unknown>\n  const keys = Object.keys(left)\n  if (keys.length !== Object.keys(right).length) return false\n  for (const key of keys) if (left[key] !== right[key]) return false\n  return true\n}\n\n/**\n * 把一批行并入分片：身份是 `row.id`（= `<sessionId>__<seq>`），后写覆盖，按 seq 升序归一。\n *\n * 三条不变量（测试钉住）：同批重复并入 → `changed: false` 且内容不变（幂等）；同 id 再次\n * 并入 → 覆盖而不是追加；批内顺序不影响结果（字节稳定，落盘文件可直接比对）。\n */\nexport function mergeShardRows(current: readonly LedgerRow[], batch: readonly LedgerRow[]): ShardMerge {\n  const byId = new Map<string, LedgerRow>()\n  for (const row of current) byId.set(row.id, row)\n  let changed = false\n  for (const row of batch) {\n    const previous = byId.get(row.id)\n    if (previous !== undefined && sameRow(previous, row)) continue\n    byId.set(row.id, row)\n    changed = true\n  }\n  // 未变时原样返回：调用方据此整片跳过 put，不必先写再比。\n  if (!changed) return { rows: current as LedgerRow[], changed: false }\n  const rows = [...byId.values()].sort((a, b) => a.seq - b.seq || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))\n  return { rows, changed: true }\n}\n"
    },
    {
      "path": "packages/plugin-usage-billing/src/service.ts",
      "content": "/**\n * ctx.usageBilling：计费聚合的 host 门面，也是 Typert Remote 服务（SRC 标记，无 codegen）。\n * 展示数据一律现算，账本行是唯一的持久事实。\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { Domain, KvTable } from '@deepseek-ai/dsh-storage-domain'\nimport { TypertRemoteService } from '@deepseek-ai/dsh-typert-protocol'\nimport type { usageBillingDomain } from './domain.ts'\nimport { aggregateOnce, resetAggregateCache } from './aggregate.ts'\nimport type { AggregateStats, SessionSource } from './aggregate.ts'\nimport { latestDiagnostic } from './diag.ts'\nimport { LedgerStore } from './ledger-store.ts'\nimport { aliasId, priceKeyCandidates } from './model-key.ts'\nimport { DEFAULT_USD_TO_CNY, priceKey } from './pricing/catalog.ts'\nimport { priceUsage } from './pricing/cost.ts'\nimport { holidayDataCovers, isCnHoliday, lastHolidayDataYear } from './pricing/holidays.ts'\nimport { nextTierSwitchAt, tierAndFactorAt, tierDayProfileAt } from './pricing/tiers.ts'\nimport type { TierStatus } from './types.ts'\nimport { CATALOG_REASONS, activeOverridesAt, diffEntries, planSnapshot, resolveLayerAt, resolveSnapshotAt } from './pricing/snapshot.ts'\nimport { USAGE_BILLING_REMOTE_METHODS, USAGE_BILLING_METHOD_NAMES } from './remote-methods.ts'\nimport type { UsageBillingSettingsAccess } from './settings.ts'\nimport { SNAPSHOT_BASE_ID, SNAPSHOT_INSTALL_ID, uniqueSnapshotDeltaKey } from './storage-key.ts'\nimport { dayKey, daysInRange, rangeToSpec } from './time.ts'\nimport type { RangeKind } from './time.ts'\nimport {\n  attachAllCny, buildByWorkspace, buildDaily, buildMarkers, buildOverview, filterRows, mergeByModel,\n} from './view.ts'\nimport type {\n  AliasInput, CustomPriceInput, Diagnostic, FoldState, LedgerRow,\n  ModelAlias, PriceEntry, PriceSnapshot,\n} from './types.ts'\n\nexport interface PricingRefreshResult {\n  ok: boolean\n  reason?: string\n  entries?: number\n  usdToCny?: number\n  /** 目录被截断，只并入了抢救到的部分。 */\n  partial?: boolean\n}\n\nexport interface UsageBillingServiceConfig {\n  domain: Domain<typeof usageBillingDomain>\n  settings: UsageBillingSettingsAccess\n  source: SessionSource\n  installAt: number\n  fetchPricing: (options: { force: boolean; ttlHours: number }) => Promise<PricingRefreshResult>\n  now?: () => number\n}\n\nexport class UsageBillingService extends TypertRemoteService {\n  private readonly ledger: LedgerStore\n  private readonly folds: KvTable<string, FoldState>\n  private readonly snapshots: KvTable<string, PriceSnapshot>\n  private readonly aliases: KvTable<string, ModelAlias>\n  private readonly diag: KvTable<string, Diagnostic>\n  private readonly config: UsageBillingServiceConfig\n  /** 价表写入串行队列：并行会让两次「读-改-写」丢掉其中一次改价。 */\n  private chain: Promise<unknown> = Promise.resolve()\n\n  /** 正在跑的聚合，本实例内合并并发调用。 */\n  private pass: Promise<AggregateStats> | undefined\n\n  /** 正在跑的账本分片重建，读路径据此跳过等待。 */\n  private rebuilding = false\n\n  constructor(ctx: Context, config: UsageBillingServiceConfig) {\n    super(ctx, 'usageBilling')\n    this.config = config\n    this.ledger = new LedgerStore(config.domain.table('ledger_shards'))\n    this.folds = config.domain.table('folds')\n    this.snapshots = config.domain.table('snapshots')\n    this.aliases = config.domain.table('aliases')\n    this.diag = config.domain.table('diag')\n  }\n\n  private now(): number { return (this.config.now ?? Date.now)() }\n\n  /** 前一次失败不让链条卡死。 */\n  private serialize<T>(work: () => Promise<T>): Promise<T> {\n    const run = this.chain.then(work)\n    this.chain = run.then(() => undefined, () => undefined)\n    return run\n  }\n\n  async ensureBaseSnapshot(entries: Record<string, PriceEntry>, usdToCny: number, usdToCnySource: 'live' | 'default'): Promise<void> {\n    return this.serialize(async () => {\n      if ([...this.snapshots.entries()].some(([, s]) => s.reason === 'install')) return\n      const snap = planSnapshot(undefined, { entries, usdToCny, usdToCnySource },\n        { id: SNAPSHOT_INSTALL_ID, at: this.config.installAt, reason: 'install' })\n      if (snap === null) return\n      await this.snapshots.put(snap.id, snap)\n      resetAggregateCache()\n    })\n  }\n\n  private aggregatePass(rebuild = false): Promise<AggregateStats> {\n    if (this.pass !== undefined) return this.pass\n    const run = aggregateOnce({\n      source: this.config.source,\n      ledger: this.ledger, folds: this.folds, diag: this.diag,\n      aliases: this.aliases, snapshots: this.snapshots,\n      // `backfilled` 按首次安装时刻算，不是本次加载时刻。\n      installAt: rebuild ? this.installSnapshotAt() : this.config.installAt,\n      now: this.config.now,\n    }, rebuild ? { force: true, rebuild: true } : {})\n    const tracked = run.finally(() => { if (this.pass === tracked) this.pass = undefined })\n    this.pass = tracked\n    return tracked\n  }\n\n  warmup(): Promise<AggregateStats> { return this.aggregatePass() }\n\n  /** `config.installAt` 每次加载都变，所以从 install 快照取。 */\n  private installSnapshotAt(): number {\n    const install = [...this.snapshots.entries()].find(([, snapshot]) => snapshot.reason === 'install')\n    return install === undefined ? this.config.installAt : install[1].at\n  }\n\n  /** 忽略水位，全部会话重折一遍，成功后落标记。 */\n  async rebuildLedger(): Promise<AggregateStats> {\n    this.rebuilding = true\n    try {\n      const stats = await this.aggregatePass(true)\n      if (stats.failures === 0) {\n        await this.config.domain.global.set({\n          rebuiltAt: this.now(), rebuiltRows: this.ledger.size, rebuiltShards: this.ledger.shardCount,\n        })\n      }\n      return stats\n    } finally {\n      this.rebuilding = false\n    }\n  }\n\n  /** 不在读路径上等整趟聚合，已有行就返回当前快照。 */\n  private async rows(): Promise<LedgerRow[]> {\n    const pass = this.aggregatePass()\n    // 重建期间不等，否则分钟级重折会卡住面板。\n    if (this.ledger.size === 0 && !this.rebuilding) await pass.catch((error: unknown) => this.reportBackgroundFailure(error))\n    else void pass.catch((error: unknown) => this.reportBackgroundFailure(error))\n    return this.ledger.all()\n  }\n\n  /** 后台失败只在这里报，抛出会打断读端点。 */\n  private reportBackgroundFailure(error: unknown): void {\n    const logger = (this.ctx as unknown as { logger?: { warn(...args: unknown[]): void } }).logger\n    logger?.warn('[plugin-usage-billing] 后台聚合失败：', error)\n  }\n\n  private scoped(rows: LedgerRow[], kind: RangeKind, includeSubagents: boolean): LedgerRow[] {\n    const spec = rangeToSpec(kind, this.now())\n    return filterRows(rows, { includeSubagents }).filter((r) =>\n      (spec.since === null || r.time >= spec.since) && (spec.until === null || r.time <= spec.until))\n  }\n\n  private listAliases(): ModelAlias[] { return [...this.aliases.entries()].map(([, a]) => a) }\n\n  async status(): Promise<{\n    installAt: number; rows: number; sessions: number; snapshots: number\n    shards: number\n    /** 账本还没就绪，这些数字不是最终值。 */\n    rebuild: { active: boolean }\n    lastDiag?: Diagnostic\n  }> {\n    const base = {\n      installAt: this.config.installAt, rows: this.ledger.size,\n      sessions: [...this.folds.entries()].length, snapshots: this.snapshots.size,\n      shards: this.ledger.shardCount,\n      rebuild: { active: this.rebuilding },\n    }\n    const latest = latestDiagnostic(this.diag)\n    return latest === undefined ? base : { ...base, lastDiag: latest }\n  }\n\n  async overview(rangeKind: RangeKind, includeSubagents: boolean) {\n    const rows = this.scoped(await this.rows(), rangeKind, includeSubagents)\n    const now = this.now()\n    const todayKey = dayKey(now)\n    const weekDays = daysInRange(rangeToSpec('7d', now), now)\n    const view = buildOverview(rows, { todayKey, weekDays })\n    const cfg = this.config.settings.get()\n    // tierDay 与 todayKey 一样是「今天」的上下文，不受 rangeKind 过滤。\n    return {\n      overview: view, todayKey,\n      budget: { enabled: cfg.budget.enabled, monthlyCny: cfg.budget.monthlyCny },\n      tierDay: tierDayProfileAt(now, isCnHoliday),\n    }\n  }\n\n  async daily(rangeKind: RangeKind, includeSubagents: boolean) {\n    const rows = this.scoped(await this.rows(), rangeKind, includeSubagents)\n    const days = daysInRange(rangeToSpec(rangeKind, this.now()), this.now())\n    return { days: buildDaily(rows, days), ...buildMarkers(rows) }\n  }\n\n  async byModel(rangeKind: RangeKind, includeSubagents: boolean) {\n    const rows = this.scoped(await this.rows(), rangeKind, includeSubagents)\n    return { models: mergeByModel(rows, this.listAliases()), ...buildMarkers(rows) }\n  }\n\n  async byWorkspace(rangeKind: RangeKind, includeSubagents: boolean) {\n    const all = await this.rows()\n    const rows = this.scoped(all, rangeKind, includeSubagents)\n    // 与 overview 用同一个 dayKey(now)。\n    const workspaces = buildByWorkspace(rows, dayKey(this.now()))\n    // 历史累计从全账本算，不能用窗口里的行。\n    attachAllCny(workspaces, all, includeSubagents)\n    return { workspaces, ...buildMarkers(rows) }\n  }\n\n  async pricing(): Promise<{\n    entries: Record<string, PriceEntry>; usdToCny: number; usdToCnySource: 'live' | 'default'\n    snapshotId: string\n    customKeys: string[]\n    /** 未生效规则时 current 为 null。 */\n    tier: TierStatus\n  }> {\n    const all = [...this.snapshots.entries()].map(([, s]) => s)\n    const now = this.now()\n    const { tier } = tierAndFactorAt(now, isCnHoliday)\n    return {\n      ...resolveSnapshotAt(now, all),\n      customKeys: Object.keys(activeOverridesAt(now, all)).sort(),\n      tier: {\n        current: tier,\n        nextSwitchAt: tier === null ? null : nextTierSwitchAt(now, isCnHoliday),\n        holidayDataThrough: holidayDataCovers(now) ? lastHolidayDataYear(now) : lastHolidayDataYear(now),\n        day: tierDayProfileAt(now, isCnHoliday),\n      },\n    }\n  }\n\n  async setCustomPrice(entry: CustomPriceInput): Promise<{ ok: true }> {\n    return this.serialize(async () => {\n      const current = await this.pricing()\n      const entries = { ...current.entries, [priceKey(entry.provider, entry.model)]: {\n        input: entry.input, cacheRead: entry.cacheRead, cacheWrite: entry.cacheWrite,\n        output: entry.output, currency: entry.currency,\n      } }\n      await this.appendDelta(entries, current.usdToCny, current.usdToCnySource, 'custom-price')\n      return { ok: true } as const\n    })\n  }\n\n  async removeCustomPrice(key: string): Promise<{ ok: boolean }> {\n    return this.serialize(async () => {\n      const current = await this.pricing()\n      const catalog = this.catalogValueOf(key)\n      const existing = current.entries[key]\n      // 目录层有价就恢复目录价；只有价全来自自定义才删 key。\n      if (existing === undefined) return { ok: false }\n      if (catalog !== undefined) {\n        const same = diffEntries({ [key]: existing }, { [key]: catalog })\n        if (Object.keys(same.entries).length === 0 && same.removed.length === 0) return { ok: false }\n      }\n      const entries = { ...current.entries }\n      if (catalog === undefined) delete entries[key]\n      else entries[key] = { ...catalog }\n      await this.appendDelta(entries, current.usdToCny, current.usdToCnySource, 'custom-price')\n      return { ok: true }\n    })\n  }\n\n  /**\n   * 目录层里该 key 的最新取值。\n   * 快照 `entries` 不是分层差分，有自定义价覆盖时会恢复出刷新前的旧目录价。\n   */\n  private catalogValueOf(key: string): PriceEntry | undefined {\n    const all = [...this.snapshots.entries()].map(([, s]) => s)\n    return resolveLayerAt(this.now(), all, CATALOG_REASONS).entries[key]\n  }\n\n  private async appendDelta(\n    entries: Record<string, PriceEntry>, usdToCny: number,\n    usdToCnySource: 'live' | 'default', reason: PriceSnapshot['reason'],\n  ): Promise<void> {\n    const all = [...this.snapshots.entries()].map(([, s]) => s)\n    // 基线是此刻之前生效的完整状态，上一条可能只是 delta。\n    const at = this.now()\n    const prev = all.length === 0 ? undefined : resolveSnapshotAt(at, all)\n    // 空表合成出的 0 汇率会让 USD 条目永远算不出钱，首条 base 要用兜底汇率。\n    const rate = prev === undefined && !(usdToCny > 0)\n      ? { usdToCny: DEFAULT_USD_TO_CNY, usdToCnySource: 'default' as const }\n      : { usdToCny, usdToCnySource }\n    const id = prev === undefined\n      ? SNAPSHOT_BASE_ID\n      : uniqueSnapshotDeltaKey(new Set(this.snapshots.keys()), reason, at)\n    const snap = planSnapshot(prev, { entries, ...rate }, { id, at, reason })\n    if (snap !== null) await this.snapshots.put(snap.id, snap)\n    resetAggregateCache()\n  }\n\n  async refreshPricing(force: boolean): Promise<PricingRefreshResult> {\n    const settings = this.config.settings.get()\n    // 刷新也是读-改-写，必须与改价走同一条串行链。\n    return await this.serialize(() =>\n      this.config.fetchPricing({ force, ttlHours: settings.pricing.refreshHours }))\n  }\n\n  async setAlias(input: AliasInput): Promise<{ ok: true }> {\n    const id = aliasId(input.provider, input.rawModel)\n    if (input.canonicalModel === null) await this.aliases.delete(id)\n    else await this.aliases.put(id, {\n      id, provider: input.provider.trim().toLowerCase(),\n      rawModel: input.rawModel,\n      // 只去空白，不要过 normalizeModelId：带日期的目录 key 必须原样保留。\n      canonicalModel: input.canonicalModel.trim(),\n    })\n    resetAggregateCache()\n    return { ok: true }\n  }\n\n  async aliasList(): Promise<{ aliases: ModelAlias[] }> { return { aliases: this.listAliases() } }\n\n  async repricing(): Promise<{ changed: number }> {\n    const all = [...this.snapshots.entries()].map(([, s]) => s)\n    const aliases = new Map(this.listAliases().map((a) => [a.id, a]))\n    let changed = 0\n    const patched: LedgerRow[] = []\n    for (const row of this.ledger.all()) {\n      if (row.priced) continue\n      const table = resolveSnapshotAt(row.time, all)\n      const alias = aliases.get(aliasId(row.provider, row.model))\n      // 按行自己的时刻判档，不能用 now。\n      const { tier, factor } = tierAndFactorAt(row.time, isCnHoliday)\n      const result = priceUsage(\n        { inputTokens: row.input, outputTokens: row.output, cacheReadTokens: row.cacheRead, cacheWriteTokens: row.cacheWrite },\n        table.entries, priceKeyCandidates(row.provider, row.model, alias), table.usdToCny, factor,\n      )\n      if (!result.priced) continue\n      patched.push({\n        ...row,\n        costCny: result.costCny,\n        currency: result.currency,\n        priced: true,\n        snapshotId: table.snapshotId,\n        ...(tier === null ? {} : { tier }),\n      })\n      changed += 1\n    }\n    await this.ledger.putMany(patched)\n    resetAggregateCache()\n    return { changed }\n  }\n}\n\n/** 手工复刻 @Remote 装饰器产物。名单与 client descriptors 共用 remote-methods.ts。 */\nconst REMOTE_METHODS = '@deepseek-ai/dsh-typert-protocol/remote-methods'\n\nfunction markRemoteMethods(prototype: object, methods: readonly string[]): void {\n  Object.defineProperty(prototype, REMOTE_METHODS, {\n    configurable: true,\n    value: Object.freeze({\n      version: 1,\n      methods: Object.freeze(methods.map((method) =>\n        Object.freeze({ method, invocation: Object.freeze({ kind: 'direct' as const }) }))),\n    }),\n  })\n}\n\nmarkRemoteMethods(UsageBillingService.prototype, USAGE_BILLING_METHOD_NAMES)\n\ndeclare module '@deepseek-ai/cordis' {\n  interface Context {\n    usageBilling: UsageBillingService\n  }\n}\n\nexport { USAGE_BILLING_REMOTE_METHODS }\n"
